"""Reusable bounded HTTP model adapter with strict response validation."""

import asyncio
import logging
import math
from collections.abc import Sequence
from dataclasses import dataclass

import httpx

from ..config.models import ModelEndpoint, ModelSettings
from ..models.model_ports import RerankScore
from ..models.service_errors import ServiceError

logger = logging.getLogger(__name__)


@dataclass(frozen=True)
class ModelLimits:
    """Local budgets; these do not claim to increase gateway capacity."""

    embedding_concurrency: int = 2
    rerank_concurrency: int = 2
    timeout_seconds: float = 20.0
    max_rerank_characters: int = 50_000

    def __post_init__(self) -> None:
        if (
            min(
                self.embedding_concurrency,
                self.rerank_concurrency,
                self.max_rerank_characters,
            )
            < 1
            or not math.isfinite(self.timeout_seconds)
            or self.timeout_seconds <= 0
        ):
            raise ValueError("Model limits must be finite and positive")


def _number(value: object) -> float:
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError("Nonfinite model score")
    return float(value)


class ModelClient:
    """Borrow one lifecycle-owned HTTP client and independently bound model requests."""

    def __init__(
        self,
        settings: ModelSettings,
        client: httpx.AsyncClient,
        limits: ModelLimits | None = None,
    ) -> None:
        limits = limits or ModelLimits()
        self.settings = settings
        self.client = client
        self.limits = limits
        self.embedding_slots = asyncio.Semaphore(limits.embedding_concurrency)
        self.rerank_slots = asyncio.Semaphore(limits.rerank_concurrency)

    async def _post(
        self,
        endpoint: ModelEndpoint,
        path: str,
        payload: dict,
        slots: asyncio.Semaphore,
    ) -> dict:
        try:
            async with asyncio.timeout(self.limits.timeout_seconds), slots:
                response = await self.client.post(
                    endpoint.base_url + path,
                    json=payload,
                    headers={"Authorization": "Bearer " + endpoint.api_key},
                    timeout=self.limits.timeout_seconds,
                )
                response.raise_for_status()
                result = response.json()
                if not isinstance(result, dict):
                    raise ValueError("Model response must be an object")
                return result
        except (httpx.HTTPError, TimeoutError, ValueError) as error:
            logger.warning(
                "model_request_failed operation=%s error_type=%s status=%s",
                path,
                type(error).__name__,
                error.response.status_code
                if isinstance(error, httpx.HTTPStatusError)
                else None,
            )
            # Upstream bodies and URLs may contain credentials or original user text.
            raise ServiceError("TEMPORARILY_UNAVAILABLE") from None

    async def embed_documents(
        self, texts: Sequence[str]
    ) -> tuple[tuple[float, ...], ...]:
        """Validate batch coverage, stable dimensions and nonzero finite vectors."""
        if not texts:
            return ()
        result = await self._post(
            self.settings.embedding,
            "/embeddings",
            {
                "model": self.settings.embedding.model,
                "input": list(texts),
                "encoding_format": "float",
            },
            self.embedding_slots,
        )
        try:
            rows = result["data"]
            if not isinstance(rows, list) or len(rows) != len(texts):
                raise ValueError("Embedding count mismatch")
            vectors = {}
            for row in rows:
                index = row["index"]
                if (
                    type(index) is not int
                    or not 0 <= index < len(texts)
                    or index in vectors
                ):
                    raise ValueError("Invalid embedding index")
                vector = tuple(_number(value) for value in row["embedding"])
                if not vector or not any(vector):
                    raise ValueError("Zero or empty embedding")
                vectors[index] = vector
            if len({len(vector) for vector in vectors.values()}) != 1:
                raise ValueError("Inconsistent embedding dimension")
            return tuple(vectors[index] for index in range(len(texts)))
        except (KeyError, TypeError, ValueError, OverflowError):
            logger.warning("model_response_invalid operation=embeddings")
            raise ServiceError("TEMPORARILY_UNAVAILABLE") from None

    async def embed_query(self, text: str) -> tuple[float, ...]:
        """Embed a single query using the same model as offline construction."""
        return (await self.embed_documents((text,)))[0]

    async def rerank(
        self, query: str, documents: Sequence[str], top_n: int
    ) -> tuple[RerankScore, ...]:
        """Submit complete texts; reject oversized input rather than silently truncate."""
        if not 1 <= top_n <= len(documents):
            raise ValueError("Invalid rerank top_n")
        if any(
            len(text) > self.limits.max_rerank_characters
            for text in (query, *documents)
        ):
            raise ServiceError("TEMPORARILY_UNAVAILABLE")
        result = await self._post(
            self.settings.rerank,
            "/rerank",
            {
                "model": self.settings.rerank.model,
                "query": query,
                "documents": list(documents),
                "top_n": top_n,
                "return_documents": False,
            },
            self.rerank_slots,
        )
        try:
            rows = result["results"]
            if not isinstance(rows, list) or len(rows) != top_n:
                raise ValueError("Rerank count mismatch")
            scores = {}
            for row in rows:
                index = row["index"]
                if (
                    type(index) is not int
                    or not 0 <= index < len(documents)
                    or index in scores
                ):
                    raise ValueError("Invalid rerank index")
                scores[index] = _number(row["relevance_score"])
            return tuple(
                RerankScore(index, score)
                for index, score in sorted(
                    scores.items(), key=lambda item: (-item[1], item[0])
                )
            )
        except (KeyError, TypeError, ValueError, OverflowError):
            logger.warning("model_response_invalid operation=rerank")
            raise ServiceError("TEMPORARILY_UNAVAILABLE") from None

"""Validated immutable filesystem publications and explicitly retained references."""

import base64
import json
import logging
from array import array
from contextlib import contextmanager
from dataclasses import dataclass
from pathlib import Path

import numpy as np
from pydantic import TypeAdapter

from ..indexing import TERMS_VERSION, TEXT_VERSION
from ..models.catalog import CatalogNode
from ..models.chunk import Chunk
from ..models.document import DocumentMetadata
from ..models.service_errors import ServiceError
from ..models.snapshot import SectionRecord
from .artifacts import checked_path, file_digest, validate_build_id
from .indexes import MemoryIndexes
from .references import key_token, snapshot_token

logger = logging.getLogger(__name__)


@dataclass(frozen=True)
class FileSnapshot:
    """One publication; old publications retain content metadata without vectors."""

    build_id: str
    root: Path
    reference_keys: dict[str, dict[str, str]]
    documents: dict[str, DocumentMetadata]
    document_files: dict[str, str]
    nodes: dict[str, CatalogNode]
    children: dict[str, tuple[str, ...]]
    sections: dict[str, SectionRecord]
    chunks: dict[str, Chunk]
    chunk_sections: dict[str, str]
    indexes: MemoryIndexes | None

    def read_document(self, doc_id: str) -> str:
        """Read exact UTF-8 source, preserving CRLF and character offsets."""
        try:
            return (
                checked_path(self.root, self.document_files[doc_id])
                .read_bytes()
                .decode("utf-8")
            )
        except (OSError, UnicodeError, KeyError, ValueError) as error:
            logger.error(
                "document_read_failed build_id=%s doc_id=%s error_type=%s",
                self.build_id,
                doc_id,
                type(error).__name__,
            )
            raise ServiceError("KNOWLEDGE_BASE_ERROR") from error


def _json(root: Path, relative: str):
    return json.loads(checked_path(root, relative).read_bytes())


def load_snapshot(
    root: Path,
    *,
    expected_build_id: str,
    expected_model: str | None = None,
    load_indexes: bool = True,
) -> FileSnapshot:
    """Reject incompatible, corrupt or incomplete artifacts before serving requests."""
    try:
        return _load_snapshot(root, expected_build_id, expected_model, load_indexes)
    except (OSError, ValueError, KeyError, TypeError, OverflowError) as error:
        raise ServiceError("KNOWLEDGE_BASE_ERROR") from error


def _load_snapshot(
    root: Path, build_id: str, model: str | None, with_indexes: bool
) -> FileSnapshot:
    validate_build_id(build_id)
    manifest = _validate_manifest(root, build_id, model, with_indexes)
    documents, document_files, nodes, children, sections = _read_catalog(
        root, manifest["files"], manifest["document_count"]
    )
    chunks, joins = _read_chunks(root, documents, sections, manifest["chunk_count"])
    indexes = _read_indexes(root, chunks, manifest) if with_indexes else None
    kinds = {
        "node": [k for k, n in nodes.items() if n.kind not in ("document", "section")],
        "doc": list(documents),
        "section": list(sections),
        "chunk": list(chunks),
    }
    references = {
        kind: {key_token(kind, key): key for key in keys}
        for kind, keys in kinds.items()
    }
    return FileSnapshot(
        build_id=build_id,
        root=root,
        reference_keys=references,
        documents=documents,
        document_files=document_files,
        nodes=nodes,
        children=children,
        sections=sections,
        chunks=chunks,
        chunk_sections=joins,
        indexes=indexes,
    )


def _validate_manifest(
    root: Path, build_id: str, model: str | None, with_indexes: bool
) -> dict:
    """Verify compatibility and every declared artifact before decoding business data."""
    manifest = _json(root, "manifest.json")
    if (
        manifest["schema_version"] != 2
        or manifest["build_id"] != build_id
        or manifest["normalization"] != "l2-float32"
        or manifest["text_version"] != TEXT_VERSION
        or manifest["terms_version"] != TERMS_VERSION
        or (with_indexes and model is not None and manifest["model"] != model)
    ):
        raise ValueError("Incompatible snapshot manifest")
    files = manifest["files"]
    required = {
        "catalog.json",
        "chunks.jsonl",
        "chunk_sections.json",
        "indexes/vectors.npy",
        "indexes/keywords.jsonl",
    }
    if not required <= files.keys():
        raise ValueError("Missing artifact declarations")
    for name, entry in files.items():
        path = checked_path(root, name)
        if (
            path.stat().st_size != entry["bytes"]
            or file_digest(path) != entry["sha256"]
        ):
            raise ValueError(f"Artifact checksum mismatch: {name}")
    return manifest


def _read_catalog(root: Path, files: dict, document_count: int):
    """Validate the tree and source character ranges before exposing content access."""
    catalog = _json(root, "catalog.json")
    documents = {
        key: TypeAdapter(DocumentMetadata).validate_python(value["metadata"])
        for key, value in catalog["documents"].items()
    }
    document_files = {key: value["file"] for key, value in catalog["documents"].items()}
    if not set(document_files.values()) <= files.keys():
        raise ValueError("Undeclared document file")
    if len(documents) != document_count or not documents:
        raise ValueError("Document count mismatch")
    texts = {
        key: checked_path(root, name).read_bytes().decode("utf-8")
        for key, name in document_files.items()
    }
    nodes = TypeAdapter(dict[str, CatalogNode]).validate_python(catalog["nodes"])
    children = TypeAdapter(dict[str, tuple[str, ...]]).validate_python(
        catalog["children"]
    )
    sections = TypeAdapter(dict[str, SectionRecord]).validate_python(
        catalog["sections"]
    )
    if set(children) != {"", *nodes}:
        raise ValueError("Catalog child map mismatch")
    visited = set()
    pending = list(children[""])
    while pending:
        key = pending.pop()
        if key in visited or key not in nodes:
            raise ValueError("Duplicate, cyclic or missing catalog node")
        visited.add(key)
        node = nodes[key]
        if node.key != key or node.has_children != bool(children[key]):
            raise ValueError("Inconsistent catalog node")
        pending.extend(children[key])
    if visited != nodes.keys():
        raise ValueError("Disconnected catalog nodes")
    for key, section in sections.items():
        if (
            key != section.key
            or nodes[key].kind != "section"
            or section.doc_id not in documents
            or not 0
            <= section.span.start
            <= section.span.end
            <= len(texts[section.doc_id])
        ):
            raise ValueError("Invalid section identity or span")
        parent = sections.get(section.parent_key) if section.parent_key else None
        if section.parent_key is not None:
            if (
                parent is None
                or parent.doc_id != section.doc_id
                or not parent.span.start
                <= section.span.start
                <= section.span.end
                <= parent.span.end
                or key not in children[parent.key]
            ):
                raise ValueError("Invalid section parent")
        elif (
            section.span.start != 0
            or section.span.end != len(texts[section.doc_id])
            or key not in children[section.doc_id]
        ):
            raise ValueError("Document root must cover the complete original")
    return documents, document_files, nodes, children, sections


def _read_chunks(root: Path, documents: dict, sections: dict, chunk_count: int):
    """Validate publication order, metadata consistency and complete section joins."""
    chunks = {}
    adapter = TypeAdapter(Chunk)
    with checked_path(root, "chunks.jsonl").open(encoding="utf-8") as stream:
        for line in stream:
            chunk = adapter.validate_json(line)
            if chunk.chunk_id in chunks or chunk.doc_id not in documents:
                raise ValueError("Duplicate chunk or missing document")
            chunks[chunk.chunk_id] = chunk
    if not chunks or len(chunks) != chunk_count:
        raise ValueError("Chunk count mismatch")
    joins = TypeAdapter(dict[str, str]).validate_python(
        _json(root, "chunk_sections.json")
    )
    if joins.keys() != chunks.keys():
        raise ValueError("Incomplete chunk section mapping")
    per_document: dict[str, list[int]] = {}
    for key, chunk in chunks.items():
        section = sections[joins[key]]
        meta = documents[chunk.doc_id]
        if (
            section.doc_id != chunk.doc_id
            or section.section_path != chunk.metadata.section_path
        ):
            raise ValueError("Chunk points to a different section")
        for field in (
            "category",
            "product",
            "version",
            "language",
            "title",
            "source_path",
            "source_url",
        ):
            if getattr(meta, field) != getattr(chunk.metadata, field):
                raise ValueError("Chunk metadata differs from its document")
        per_document.setdefault(chunk.doc_id, []).append(chunk.chunk_index)
    if any(indices != list(range(len(indices))) for indices in per_document.values()):
        raise ValueError("Chunk order is not contiguous")
    return chunks, joins


def _read_indexes(
    root: Path, chunks: dict[str, Chunk], manifest: dict
) -> MemoryIndexes:
    """Validate normalized rows and posting bounds before enabling retrieval."""
    vectors = np.load(checked_path(root, "indexes/vectors.npy"), allow_pickle=False)
    if (
        vectors.dtype != np.float32
        or vectors.shape != (len(chunks), manifest["dimension"])
        or manifest["dimension"] < 1
        or not np.isfinite(vectors).all()
        or not np.allclose(np.linalg.norm(vectors, axis=1), 1, atol=1e-5)
    ):
        raise ValueError("Invalid normalized vector matrix")
    keywords = _read_keywords(root, len(chunks))
    if len(keywords) != manifest["keyword_count"]:
        raise ValueError("Keyword count mismatch")
    return MemoryIndexes(chunks, vectors, keywords)


def _read_keywords(root: Path, chunk_count: int) -> dict[str, array]:
    """Decode one posting at a time; retain compact unsigned integers, not Python ints."""
    keywords: dict[str, array] = {}
    with checked_path(root, "indexes/keywords.jsonl").open(encoding="utf-8") as stream:
        for line in stream:
            record = json.loads(line)
            if not isinstance(record, list) or len(record) != 2:
                raise ValueError("Invalid keyword record")
            term, rows = record
            if (
                not isinstance(term, str)
                or term in keywords
                or not isinstance(rows, list)
                or not rows
            ):
                raise ValueError("Invalid or duplicate keyword term")
            previous = -1
            for row in rows:
                if type(row) is not int or not previous < row < chunk_count:
                    raise ValueError("Invalid keyword postings")
                previous = row
            keywords[term] = array("I", rows)
    return keywords


class FileSnapshotStore:
    """Select only preloaded publications; references can never become disk paths."""

    def __init__(
        self, current: FileSnapshot, retained: tuple[FileSnapshot, ...] = ()
    ) -> None:
        self.current = current
        self.snapshots = {snapshot_token(s.build_id): s for s in (current, *retained)}
        if len(self.snapshots) != 1 + len(retained):
            raise ValueError("Duplicate snapshot IDs")

    @contextmanager
    def acquire(self, reference: str | None = None):
        """Pin a publication throughout a request, including its cleanup."""
        if reference is None:
            yield self.current
            return
        if reference.startswith(("node_", "doc_", "section_", "chunk_")):
            parts = reference.split("_")
            if len(parts) != 3 or any(
                len(part) != 64 or any(c not in "0123456789abcdef" for c in part)
                for part in parts[1:]
            ):
                raise ServiceError("INVALID_ARGUMENT")
            token = parts[1]
        else:
            try:
                cursor = json.loads(
                    base64.b64decode(
                        reference.encode("ascii"), altchars=b"-_", validate=True
                    )
                )
                token = cursor["snapshot"]
                if not isinstance(token, str):
                    raise ValueError("Invalid snapshot token")
            except (ValueError, KeyError, TypeError, UnicodeError) as error:
                raise ServiceError("INVALID_CURSOR") from error
        snapshot = self.snapshots.get(token)
        if snapshot is None:
            raise ServiceError("STALE_REFERENCE")
        yield snapshot

"""Required deployment configuration, read only when opening production resources."""

import math
import os
from dataclasses import dataclass, field
from pathlib import Path

from dotenv import dotenv_values

from .models import ModelSettings, load_model_settings


@dataclass(frozen=True)
class RuntimeSettings:
    """Validated values; no live connection or client is stored here."""

    snapshot_root: Path
    current_build: str
    retained_builds: tuple[str, ...]
    database_url: str = field(repr=False)
    models: ModelSettings
    compute_workers: int = 2
    database_pool_size: int = 4
    database_timeout_seconds: float = 2.0
    embedding_concurrency: int = 2
    rerank_concurrency: int = 2
    model_timeout_seconds: float = 20.0
    allow_rerank_degradation: bool = True


def load_runtime_settings(env_file: Path | None = None) -> RuntimeSettings:
    """Fail startup clearly if a required dependency has not been configured."""
    values = dotenv_values(env_file, interpolate=False) if env_file else {}
    values.update(os.environ)

    def required(name: str) -> str:
        value = values.get(name)
        if not value or not value.strip():
            raise ValueError(f"Missing configuration field: {name}")
        return value.strip()

    def integer(name: str, default: int) -> int:
        try:
            value = int(values.get(name, str(default)))
            if value < 1:
                raise ValueError()
            return value
        except (TypeError, ValueError):
            raise ValueError(f"Invalid configuration field: {name}") from None

    def seconds(name: str, default: float) -> float:
        try:
            value = float(values.get(name, str(default)))
            if not math.isfinite(value) or value <= 0:
                raise ValueError()
            return value
        except (TypeError, ValueError):
            raise ValueError(f"Invalid configuration field: {name}") from None

    degradation = values.get("MCP_ALLOW_RERANK_DEGRADATION", "true")
    if degradation not in ("true", "false"):
        raise ValueError("Invalid configuration field: MCP_ALLOW_RERANK_DEGRADATION")
    return RuntimeSettings(
        snapshot_root=Path(required("MCP_SNAPSHOT_ROOT")).expanduser(),
        current_build=required("MCP_CURRENT_BUILD"),
        retained_builds=tuple(
            v.strip()
            for v in (values.get("MCP_RETAINED_BUILDS") or "").split(",")
            if v.strip()
        ),
        database_url=load_database_url(env_file),
        models=load_model_settings(env_file),
        compute_workers=integer("MCP_COMPUTE_WORKERS", 2),
        database_pool_size=integer("MCP_DATABASE_POOL_SIZE", 4),
        database_timeout_seconds=seconds("MCP_DATABASE_TIMEOUT_SECONDS", 2),
        embedding_concurrency=integer("MCP_EMBEDDING_CONCURRENCY", 2),
        rerank_concurrency=integer("MCP_RERANK_CONCURRENCY", 2),
        model_timeout_seconds=seconds("MCP_MODEL_TIMEOUT_SECONDS", 20),
        allow_rerank_degradation=degradation == "true",
    )


def load_database_url(env_file: Path | None = None) -> str:
    """Allow migrations without requiring model or snapshot configuration."""
    values = dotenv_values(env_file, interpolate=False) if env_file else {}
    # Deployment environment overrides local files, including the legacy alias.
    for source in (os.environ, values):
        for name in ("DATABASE_URL", "MCP_DATABASE_URL"):
            if name in source:
                value = source[name]
                if value and value.strip():
                    return value.strip()
                raise ValueError("Missing configuration field: DATABASE_URL")
    raise ValueError("Missing configuration field: DATABASE_URL")

"""Search orchestration; model I/O is separate from bounded local computation."""

import logging

from ..indexing import render_index_text
from ..models.model_ports import RetrievalModels
from ..models.retrieval import RetrievalQuery, SearchEvidence, SearchHit
from ..models.service_errors import ServiceError
from ..services.compute import ComputeExecutor
from ..services.ports import Snapshot
from .ranking import fuse_rankings, recall_dense, recall_keywords, select_candidates
from .scope import resolve_scope

logger = logging.getLogger(__name__)


class SearchPipeline:
    """Coordinate filtering, retrieval and optional rerank degradation."""

    def __init__(
        self,
        models: RetrievalModels,
        compute: ComputeExecutor,
        *,
        allow_rerank_degradation: bool = True,
    ) -> None:
        self.models = models
        self.compute = compute
        self.allow_rerank_degradation = allow_rerank_degradation

    async def search(
        self, query: RetrievalQuery, *, snapshot: Snapshot
    ) -> SearchEvidence:
        """Return source-bound evidence; never truncate candidates or generate answers."""
        scope, ids = await self.compute.run(resolve_scope, query, snapshot)
        if not ids:
            return SearchEvidence(scope, "skipped", ())
        if snapshot.indexes is None:
            raise ServiceError("KNOWLEDGE_BASE_ERROR")
        vector = await self.models.embed_query(query.text)

        def rank():
            dense = recall_dense(vector, ids, snapshot.indexes)
            keywords = recall_keywords(query.text, ids, snapshot.indexes)
            return select_candidates(fuse_rankings(dense, keywords), query.top_k)

        try:
            candidates = await self.compute.run(rank)
        except ValueError as error:
            raise ServiceError("TEMPORARILY_UNAVAILABLE") from error
        chosen = candidates[: query.top_k]
        status = "skipped"
        if len(candidates) > 1:
            texts = [
                render_index_text(
                    snapshot.chunks[key].metadata, snapshot.chunks[key].content
                )
                for key in candidates
            ]
            try:
                scores = await self.models.rerank(query.text, texts, len(chosen))
                chosen = tuple(candidates[score.index] for score in scores)
                status = "applied"
            except ServiceError as error:
                if (
                    error.code != "TEMPORARILY_UNAVAILABLE"
                    or not self.allow_rerank_degradation
                ):
                    raise
                logger.warning("rerank_degraded code=%s", error.code)
                status = "degraded"
        return SearchEvidence(
            scope,
            status,
            tuple(
                SearchHit(snapshot.chunks[key], snapshot.chunk_sections[key])
                for key in chosen
            ),
        )
